import './index.css';
import FourierVisualiser from './project-files/fourier-visualiser'
import Harmonics from './project-files/harmonics'

import { useState } from 'react'


function Projects() {
    const [ isFourier, setFourier ] = useState(false);
    const [isCGOL, setCGOL] = useState(false);
    return (
        <div className="HomePage">
            <div className="Project" id="Buttons">
                <button onClick={() => {setFourier(!isFourier)}} className="ProjectButton">Fourier Visualiser</button>
                <button onClick={() => {setCGOL(!isCGOL)}} className="ProjectButton">Harmonics</button>
            </div>
            <div className="Project" id="ProjectWindow">
                {isFourier ? <FourierVisualiser/> : ""}
                {isCGOL ? <Harmonics/> : ""}
            </div>
        </div>
    );
}

export default Projects;