import "./index.css";
import { useState, useEffect, useRef } from "react";
import { SocialIcon } from 'react-social-icons';

const first_article_text = (
<p>This is the home page of my personal website where I share my projects, music, bike trip experiences,
    and more about myself. Feel free to explore the different sections using the sidebar navigation.</p>
);

// const title_text = "mark cornes"
const title_text = "...hello there, visitor!"
let i = 0;

function TypewriterEffect() {
    if (i < title_text.length) {
        document.getElementById("TypedText").innerHTML += title_text.charAt(i);
        i++;
        setTimeout(TypewriterEffect, 100);
    }
}

function MakeTitle() {
    const [typed, setTyped] = useState(false);
    return (
        <div className="HomeTitleContainer"
        onClick={() => {if(!typed) {TypewriterEffect()};
        setTyped(true);
        }}
        >
            <div className="HomeTitle">
                <h1>...mark cornes...</h1>
            </div>
            <div className="Links">
                <SocialIcon url='https://github.com/markcornes' className="LinksItem"/>
                <SocialIcon url='https://www.youtube.com/@MarkCornes' className="LinksItem"/>
                <SocialIcon url='https://www.instagram.com/mark._.cornes/' className="LinksItem"/>
                <SocialIcon url='https://www.strava.com/athletes/122838370' className="LinksItem"/>
            </div>
            <div className="SubTitle" id="TypedText">&gt;&gt;&nbsp;</div>
        </div>
    );
}

function MakeArticle(title, content) {
    return (
        <div className="Article">
            <h2>{title}</h2>
            {content}
        </div>
    );
}

function MakeImage(url) {
    return (
        <div className="ArticleImageBox">
            <img src={url} alt="image" width="500" className="ArticleImage" onClick={null}/>
        </div>
    );
}


function Home() {
    const article_two_content = (
        <>
            {MakeImage("https://i.imgur.com/JDJpwwW.jpg")}
            <p>And some text too...</p>
            {MakeImage("https://i.imgur.com/80Tvxpxl.jpg")}
            <p>Then more text!</p>
        </>
    );

    return (
        <div className="HomePage">
            {MakeTitle()}
            {MakeArticle("Welcome to My Personal Site!", first_article_text)}
            {MakeArticle("Article with Image!", article_two_content)}
            {MakeArticle("Article 2!", "Let's see if this works...")}
            {MakeArticle("Article 2!", "Let's see if this works...")}
            {MakeArticle("Article 2!", "Let's see if this works...")}
        </div>
    );
}

export default Home;